package com.hospital.system.controller; import com.hospital.system.model.Bill; import com.hospital.system.dto.*; import com.hospital.system.service.BillingService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/bills") public class BillingController {private final BillingService s; public BillingController(BillingService s){this.s=s;} @GetMapping public Object all(){return s.all();} @GetMapping("/{id}") public Bill one(@PathVariable Long id){return s.one(id);} @PostMapping public ResponseEntity<Bill> add(@Valid @RequestBody BillRequest x){return ResponseEntity.status(201).body(s.create(x));} @PostMapping("/{id}/items") public Bill item(@PathVariable Long id,@Valid @RequestBody BillItemRequest x){return s.addItem(id,x);} @DeleteMapping("/{id}/items/{itemId}") public ResponseEntity<Void> remove(@PathVariable Long id,@PathVariable Long itemId){s.removeItem(id,itemId);return ResponseEntity.noContent().build();} }
